'实非能饮姑好客，不时斗酒由人须',
'众宾捧酒寿主人，将军自是擎天柱',
'旧日名城酒，他时梦境灯',
'茅柴一杯酒，相对奈愁何',
'一鸟闹红春欲动，酒帘正在杏花西',
'饮酒不计斗，褚无一丝藏',
'将军羔酒空作梦，十年未有今年贫',
'入衢酒无声，道信山辞涴',
'饮酒端不恶，为米知何奈',
