'不知今朝是生旦，东邻旋问酒可赊',
'何如北窗卧，酒熟巾自漉',
'把酒更何辞，一对西风笑',
'今朝捧酒祝亲意，不知何者堪比方',
'直须酿酒如春红，岁岁称觞无了毕',
'客来煮茗话畴昔，酒熟春禽相劝酬',
'吾翁今年九十一，儿从两岁贫无酒',
'虽无旨酒奉杯酌，意乐心宽亲自寿',
'喜有诗情浓似酒，从渠日历积如山',
'秋风日有酒杯乐，径石时敲拄杖声',
'把酒哦诗真不恶，此时怀抱十分开',
'山下江清水见沙，杖头沽醉酒旗家',
'乘兴半春携酒约，隔山遥夜读书声',
'柴门终日掩荒苔，记得年时把酒杯',
'而今头白灯明里，有酒何妨一醉红',
'多病近来常止酒，及无尊俎欠风流',
'道人雅好惟清供，却恐花神索酒觞',
'只今天一涯，把酒远相属',
'连日天街候驾归，且呼酒对早梅飞',
'饮中诸公人中豪，左手酒杯右手螯',
'酒可醺兮苹可羞，灵不鄙兮摅吾愁',
'啜醨正自强持酒，众醉如何敢独醒',
'兴来莫问酒中圣，且把金杯和月吞',
'萱草轩窗处处幽，酒中不着客中愁',
'何处望飞凫，山中酒初熟',
'坐对长沙酒，空伤夜雨神',
'苦无杯酒暇，人事正纷如',
'凭窗风日爽，诗酒可盘桓',
'酒量春吞海，诗肩夜耸山',
'论心岂无酒，举盏不忍空',
'不图尘土中，得共一尊酒',
'何时一壶酒，挂席上严濑',
'主人应飘洒，何时同酒卮',
'夜饮不计酒，晓骑驰霜明',
'东风吹眼明，倏然如酒醒',
'人生贵相亲，风味入杯酒',
'清霜水南夜，海运一杯酒',
'有酒不为饮，奈此好事何',
'赖有田中邻，时时遣酒至',
'一见邀我留，取酒置盘飧',
'抚我百醉诗，把此一杯酒',
'举手酬座人，酒美翁不归',
'心亲相往来，岂计酒浊清',
'雨凉梅熟樽酒地，旧人家藏欣见之',
'主人犹有酒浇愁，旦起相呼相煖热',
'同僚鬭牛应暖热，中酒过厅不可说',
'不须酒畔狂吟里，梦破寒亭自惊起',
'别酒无用鲸吸川，芝山杖藜湖接天',
'酒饮诗成可奈何，坐想斯人消吝鄙',
'归来煖杯酒，炉火夜深红',
'荐福湖边酒，能来为一中',
'湖山常尽日，樽酒或谈天',
'留连一杯酒，还我旧家风',
'一自南台酒，公今成古人',
'惜春惟付酒杯深，不特年龄老鬓侵',
'相思真隠山前路，寒食酒杯终日晴',
'试倾浊酒泛黄华，节物于人自可嘉',
'宋玉谩悲陶令醉，我何杯酒啸歌时',
'本自倦吟仍止酒，渔樵何事破寒归',
'客至不劳闲酒食，一瓯茶炷一炉熏',
'秋风古寺一杯酒，老觉心情只欲闲',
'无酒无诗只意行，水边林下偶然晴',
'吟到有诗端自肯，醉中因酒亦天全',
'凌风却月诗何在，全藉清香发酒杯',
'我挟两儿同二友，老年酒外更何营',
'看来先自花饶笑，兴到从他酒入唇',
'稻田陂水菊花天，新筑轩窗醉酒边',
'酒泛椒花知逼岁，瓶簪梅蘂欲争春',
'山郡野花共酒盏，天街官柳望吟篇',
'一再相逢把酒杯，老年怀抱为君开',
'今古情怀只如此，几多杯酒可销愁',
'北关门外一杯酒，潮水庙山滩上舟',
'晴日暖风花影外，清歌妙舞酒船浮',
'与君莫放酒杯空，是事无过一笑中',
'与君扶路乘残酒，清夜醒来梦亦新',
'江湖吹雁一声秋，便合如人酒拍浮',
'人间襟韵须吟笔，花底风流入酒杯',
'好事肯同携酒至，青春又见隔年还',
'锦笺欲写相思字，谁记伤春病酒时',
'海棠红点春风里，更约相从酒数行',
'记得青岩载酒时，僧窗吹雨夜檐低',
'知我京华老无力，满壶清酒载勤渠',
'收得巩郎诗一卷，归来杯酒话吟窗',
