'夜静岸花吹浪远，酒阑山气与云浮',
'所须杯酒相料理，市酤不堪甜且酸',
'儿曹昨过故人家，归说渠侬酒味佳',
'讼庭既简无过酒，官路何嫌不到诗',
'不待他年说旧游，相逢杯酒懒回头',
'一笑春情付杯酒，乱香飘荡落梅花',
'试以闲身供酒盏，也知人与我能同',
'殷勤饷酒山中客，独酌遥知懒独登',
'我携茗酒奠荒草，寒雨吹风泪湿烟',
'酒徒他日如相问，为拂尘埃看姓名',
'渔翁饮酒得钱去，一叶如飞烟水暮',
'判断湖山诗有按，追呼风月酒随司',
'草残木尽又春来，辜负梅花与酒杯',
'明朝酒醒春犹在，更向长潭上小舟',
'日暮欢呼走妻子，买鱼沽酒歌春风',
'水清知酒美，山瘦识民贫',
'闲来立断清风影，一片飞香落酒杯',
'莫惜朝来准酒钱，渊明身即是花仙',
'心吐肺肝所同然，尊酒论文日终晷',
