'去年把酒诸子与，月落尊空未归去',
'把酒伤春暮，何人慰寂寥',
'明年枢府为公寿，慷慨还知酒量宽',
'所愧微官相束缚，何因共访酒家帘',
'锦屏残睡思忡忡，心绪无聊酒易中',
