'每伤道路销时序，但屈心情入酒杯',
'月闲花院掩，风软酒帘斜',
'重阳樽酒伴，不见牡丹花',
'酒随花谢减，心为水凉开',
'西风日紧重阳近，忍对黄花把酒卮',
