'夜半酒醒银烛冷，月移凉梦过西楼',
'相望各千里，相逢酒一壶',
'何时一樽酒，往酹与子同',
'万里秋光酒一钟，别来木末几西风',
'郭内无田负郭居，酒中有趣酒尊疏',
'公子载与归，樽酒日相娱',
'他时一樽酒，重赴山僧约',
'今年稻肥家有酒，万事且付无何有',
'慷慨论交酒一钟，别来木末几西风',
'春风吹酒醒，始知身是客',
'酒阑人散最关情，一雁西飞楚天碧',
'酒醒愁难醒，春归客未归',
