'床头金尽酒尊空，枥马相看涙如洗',
'夜永灯相守，愁深酒细倾',
'骏马不用换美妾，名酒不用博凉州',
'夜归湖上酒初醒，庄舍萧条灯火冷',
'少年虽狂犹有限，遇酒时能傲忧患',
'即今狂处不待酒，混混长歌老岩涧',
'新酒𥬠成桑正落，美人信断雁空归',
'爱书不厌如平壑，戒酒新严似筑堤',
'高楼倾美酒，一醉不容失',
'酒浪欲争湖水绿，花光却妒舞衫红',
'桥外波如鸭头绿，杯中酒作鹅儿黄',
'窗明竟无寐，卯酒倒残榼',
