'饮酒已衰犹爱客，著书初毕可藏山',
'万事看山差入眼，百年把酒独关身',
'少年喜任侠，见酒气已吞',
'一春衰病集残骸，太息流尘覆酒杯',
'虽非爱酒伴，犹是别花人',
'收拾吟笺停酒椀，年来触事动忧端',
'铜壶玉酒我径醉，短发垂肩蓬不栉',
'一杯浊酒颓然睡，恍似金牛夜下程',
'风逓钟声云外寺，水揺灯影酒家楼',
