'灯火市楼知酒贱，歌呼村路觉年丰',
'半杯浊酒如欺老，一点青灯欲诉愁',
'酒徒云散无消息，水榭凭栏泪数行',
'仕宦愈知林下贵，穷愁方策酒中勋',
'家贫悔嗜酒，年迈思学道',
'一官空作读书祟，五斗不供沽酒资',
'念当载酒醉花下，破晓啼莺先唤人',
'催花初过社公雨，对酒喜烹溪友鱼',
'世无鲁国真男子，心忆高阳旧酒徒',
'饥餐一箪饭，闷酌一卮酒',
'但办对花频举酒，莫横重九在胸中',
'六月海风吹溽暑，瓜田白酒稔清香',
'把酒聊能慰余景，乘欢不厌夕阳时',
'临流一举酒，可以喻悲伤',
'举酒酒非浅，明朝谁重觞',
'都无惜春意，樽酒为谁倾',
'杯中无浊酒，案上唯丹经',
'胜酒人自私，粒食谁尔唤',
'公秫时为酒，晨庖日有鱼',
'来邀食有鱼，屡过贫无酒',
'斗酒从故人，篮舆傲华绂',
'聊酌山酒别，独吟夜灯青',
'长桥人绝声，举酒逢秋露',
'举酒不能效时俗，半醉苦语资立身',
'醉来事事能生感，谁道愁肠酒易销',
'贵来不以屈，饮酒且逍遥',
'有斗岂不柄，何惮挹酒浆',
'是时祠臣出不意，酒半使赋或气萎',
'指以年齿衰，非酒何养气',
'昨夕梦见之，谓须多置酒',
'教雏叫噪日群集，岂有劝酒花下倾',
'犹胜昔无酒，持望白衣来',
'中酒作暴谑，心亲语多剧',
'薄酒继以斟，不觉寒日没',
'猎归炽火燎雉兔，相呼置酒喜欲狂',
'春寒催唤客尝酒，夜静卧听儿读书',
'我老畏作病，杯酒久不持',
'酒解夜过半，出门步中庭',
'同舍破甘醒宿酒，故人折简索新诗',
'饮酒不尽觞，观棋不竟局',
'画楼酒斾滴残雨，绿树莺声催暮春',
'次公醒狂何必酒，直谅多闻俱可友',
'酒市雨余青斾重，河桥风爽紫骝嘶',
'露布捷书天上去，军咨祭酒幄中谋',
'老眼阅人真烂熟，壮心得酒旋消磨',
'微风吹颊酒初醒，落日舟横杜若汀',
'酒酣起舞风前袖，兴尽回桡月下舟',
'忆过西州乐饮时，百车载酒万花围',
'倒尽酒壶终日醉，卧听儿诵半山诗',
'佳时幸无事，酒尽更须添',
'青山白云翁，放浪酒中死',
'晨开一卷书，暮把一卮酒',
'岁月惟须付樽酒，江山竟是属渔矶',
'诗情酒兴常相属，堪笑傍人说寂寥',
'床头有酒敌霜风，诗成老气尚如虹',
'心清便独夜，酒尽怯新寒',
'曩时对酒不敢饮，侧睨旁观皆贝锦',
'还家一杯酒，未畏暮风饕',
'锦江赋诗忽万里，蓬山把酒今三年',
'屏掩轻寒酒半消，断香残梦两无憀',
'雨声工破睡，酒力不禁愁',
'一櫂悠然去，东风吹酒醒',
'寸心未与年俱老，万事惟凭酒暂忘',
'社肉如林社酒浓，乡邻罗拜祝年丰',
'倒壶犹有莫春酒，开卷遂无初夏诗',
'水车罢踏戽斗藏，家家买酒歌时康',
'酒似粥𬪩知社到，饼如盘大喜秋成',
'忘忧自古无上策，欲饮家贫酒杯迮',
'衰病不禁天色恶，笑谈谁共酒尊开',
'酒户渐增诗兴在，天容此老剩狂颠',
'醉叟卧途知酒贱，耕农满野喜时平',
'吴盐雪花白，村酒粥面浓',
'蓬窗一杯酒，自觉胆轮囷',
'野风萧瑟知秋早，社酒淋漓喜岁穰',
'舴艋为家云作友，流年尽付樽中酒',
'酒肉如山鼓吹喧，车马结束有行色',
'桑落可酿酒，草枯可呼鹰',
'何当踏深雪，就饮湖桥酒',
'不耐青灯写孤影，聊呼薄酒慰长饥',
'窗间月出见梅影，枕上酒醒闻雁声',
'人沽村市酒，马啮山坡麦',
'敛付两奁来对酒，泠泠听我诵新诗',
'樽中无酒但清坐，架上有书犹纵观',
'薄酒犹堪醉，归来稚子扶',
'安得玄冥正时令，红炉绿酒一开颜',
'酒惟排闷难中圣，茶却名家可作经',
'酒瓮石边孤店晚，樵风溪畔早梅春',
'山色危栏角，梅花绿酒边',
'典衣取酒那论价，秉烛看花每到明',
'幸有春衣堪换酒，道边醉卧示神通',
'余年亦自惜，未忍付酒杯',
'麦野桑村有酒徒，过门相觅醉相扶',
'更叹衰孱不禁酒，地黄一盏即颓然',
'泥深散酒市，风恶恼灯天',
'病无诗一字，穷赖酒三升',
'雪后梅花初半吐，身闲樽酒盍频开',
'峭寒漠漠入重貂，酒力欺人凝不消',
'只欲从今都扫尽，剩沽春酒答新春',
'年丰租税无逋负，酒熟乡邻递送迎',
'兴来尚能气吞酒，诗成不觉泪渍笔',
'酒喜新𥬠绿，橙如故岁黄',
'年丰称贷少，酒贱往来频',
'忽然名在白简中，一櫂还家倾腊酒',
'禹庙兰亭俱在眼，剩沽春酒破春愁',
'贫舍久疏罗酒浆，客来不复倒衣裳',
'市楼卖酒日千斛，众人皆乐君胡忧',
'生来不啜猩猩酒，老去那营燕燕巢',
'从今剩把花前酒，忧患都空量自宽',
'罾船归处鱼餐美，社瓮香时黍酒浑',
'去年小稔已食足，今年当得厌酒肉',
'送酒无苏州，一醉未易得',
'曾携一鹤过岳阳，满城三日闻酒香',
'呼儿持故襦，买酒具一醉',
'酒尤不可缓，倾听糟床注',
'遇酒幸一醉，遇饭幸一饱',
'桑麻蒙翳不通邻，耽酒颓然一老民',
'一樽浊酒西窗下，安得无功与共斟',
'野人喜我偶闲游，取酒匆匆劝小留',
'兴来到处沽新酒，不为闲愁要破除',
'花前有酒不肯狂，回首朱颜已非昨',
'语离聊一醉，不恨村酒浑',
'好事时供沽酒费，拥途争笑插花颠',
'迨酒贱时须痛饮，得人扶处尽闲行',
'路似掌平身自倦，酒如土贱箧常悭',
'钓鱼樵风泾，买酒石帆山',
'有酒一樽聊自适，藏书万卷未为贫',
'诗无杰思知才尽，酒有残杯觉气衰',
'大网截江鱼可脍，高楼临路酒如油',
'少年岂知酒，借醉以作狂',
'努力更思恢道术，酒杯虽把不须深',
'小疾不妨寻酒去，丰年偶及挂冠初',
'一炉丹熟定不死，半瓮酒香安得愁',
'药尽无如医偃蹇，囊空那办酒逡巡',
'我诗非大手，我酒亦小户',
'床头酒瓮寒难熟，瓶里梅花夜更香',
'迟日园林尝煮酒，和风庭院㫰新丝',
'囊中钱尽罢沽酒，涧底雨寒愁束薪',
