'从来未识苏司业，愁绝西风满酒旗',
'长戈白如霜，烂漫载牛酒',
'过店亦沽酒，登山时跨驴',
'僧院轩窗酒市楼，过门自入不须留',
'客来时淡话，酒后亦高歌',
'菜细簇花宜薄饼，酒香浮螘泻长瓶',
