'梅雨初晴湖水满，未妨把酒细哦诗',
'葵苋登盘酒可赊，岂知扶病又离家',
'小楼酒旆阑街处，深巷人家晒练时',
'但报家僮多酿酒，一栏红药是归期',
'画帘不卷闻人语，玉勒徐行避酒旗',
'酒尽不妨沽巷口，诗成多是在车中',
'正如啜名酒，虽爱不忍釂',
'脱裘取酒藉芳草，与子共醉壶中春',
'吏来屡败哦诗兴，雨作常妨载酒行',
'无复官楼沽酒美，但烦湖水照衰容',
'百钱浊酒浑家醉，六月飞蚊彻晓无',
'酒旗阑道出，风浪拍船鸣',
'朱门漫设千杯酒，青壁宁无一把茅',
'药苗可𣃁携长镵，黍酒新成压小槽',
'纤手削瓜刀似水，小罂分酒盏如空',
'药裹不离手，对酒盘无梨',
'酌酒浅深须在我，更衣单复要随时',
'大度乾坤容纵酒，多情风月伴垂纶',
'酒似交情薄，愁随夜漏长',
'天色渐分寒更力，道傍沽酒坼官泥',
'药园夜啸丹台月，酒市秋听紫阁钟',
'春前腊后物华催，时伴儿曹把酒杯',
'睡少不关茶作祟，愁多却赖酒时浇',
'不管诗人大瘦生，但念酒徒稀醉眠',
'乐事久归孤枕梦，酒痕空伴素衣尘',
'白羊绿酒争下担，长笛腰鼓纷如织',
'酒旗摇摇截官道，归家未迟君试尝',
'世上漫言天爱酒，古来宁有地埋忧',
'微风起秋色，樽酒亦时开',
'楼角西南月一钩，晚瓜落刃酒新𥬠',
'读书眼力衰难强，对酒心情薄欲无',
'西窗一樽酒，亦足慰无聊',
'草草一尊酒，为汝手自倾',
'酒垆强挽人同醉，散去何曾识是谁',
'长亭结束秋将晚，别酒凄凉日易斜',
'诗酒平生乐，无如老病侵',
'渔村酒市本无期，小蹇扁舟信所之',
'细径僧归云外寺，疏灯人语酒家楼',
'酒家报我新醅熟，且拨闲愁寄一欣',
'竹院篝灯留度宿，旗亭夸酒劝无归',
'买酒贫为祟，登山病不禁',
'墙隅蔬可挽，巷口酒可赊',
'老夫解酲不用酒，自有千顷菰蒲声',
'白鹤峰前试吏时，尉曹诗酒乐新知',
'读书无定课，饮酒不成酲',
'浊酒未倾心已醉，长歌欲发涕先流',
'太山并蚁垤，俱向酒中平',
'陶公老去但浊酒，管老归来惟白襦',
'百岁光阴半归酒，一生事业略存诗',
'体倦尚凭书引睡，心安不假酒攻愁',
