'椎牛酾酒千人帐，破浪凌风万斛船',
'新丰买酒慰无聊，冲雪骑驴上灞桥',
'山林自古流觞地，弦管谁家送酒声',
'病知贪酒害，老悔爱花狂',
'酒瓮山边古钓矶，沙鸥与我共斜晖',
'川云漠漠雨冥冥，浊酒闲倾不满瓶',
'有客可剧谈，有酒可尽醉',
'山坞风烟僧院路，河梁灯火酒家楼',
'美酒得钱犹可致，高人折简孰能呼',
'村酒甜酸市酒浑，犹胜终日对空樽',
'岂无一樽酒，亦有书在傍',
'清心不醉猩猩酒，省事那营燕燕巢',
'巢山远下湿，止酒谢中干',
'霜晚知荞熟，山寒喜酒𬪩',
'不嫌村酒恶，也复醉如泥',
'更喜友生能饷酒，欣然一醉倒长瓶',
'无酒可倾殊省事，有诗浑忘亦良筹',
'雪前雪后梅初动，街北街南酒易赊',
'典衣沽酒莫辞醉，自有梅花为解酲',
'市墟买酒何人识，僧合煎茶欠客同',
'酒能忘事物，不过在醉时',
'自怜善用短，时诵止酒诗',
'偶得一瓢酒，邻里聊相寻',
'乌桕阴中把酒杯，山园处处熟杨梅',
'西风吹散朝来酒，依旧衰颜似叶黄',
'冷落秋风把酒杯，半酣直欲挽春回',
'店家已卖新𥬠酒，一醉今宵似可成',
'摇落园林探借春，耄期诗酒肯输人',
'花残狂有限，酒熟闷无多',
'细书如助懒，薄酒不成狂',
'闲愁正得酒弹压，此夕预知当熟眠',
'读书虽复具只眼，贮酒其如无别肠',
'移灯自看竛竮影，取酒时浇礧磈胸',
'剩储名酒待梅开，净扫虚窗候月来',
'闷里不嫌村酒薄，瘦来偏觉旧衣宽',
'但须晨起一卮酒，聊洗人间千种愁',
'余日真几何，得酒且伸眉',
'村场酒薄亦有力，把盏相娱不辞釂',
'酒空人散寂无声，为君试作苏门啸',
'我非恶旨酒，好饮而不能',
'城南藉草可痛饮，安得酒肠如海宽',
'良晨不把酒，新燕解相嘲',
'贫犹能酿酒，病不废游山',
'犹恨非远公，无酒遣我斟',
'儒生可逐惟求忘，社酒常辞不怕聋',
'饮酒何尝能作病，登楼是处可消忧',
'平生偶有爱山僻，垂老常无沽酒资',
'社近家方𥬠浊酒，客来身自扫苍苔',
'惟愁杀风景，无酒作重阳',
'杖得轻坚余可略，酒能醇劲更何求',
'山路近行犹百里，酒杯一举必三升',
'买酒不浇胸礌磈，忧时空觉胆轮囷',
