'白首惟诗酒，青山自主宾',
'归当访仙隠，相对酒盈缸',
'客路一杯茅店酒，相逢僧亦话生涯',
'长记钓蓑披雪去，砖炉温酒煮溪鱼',
'昼日追凉到冷泉，晚风呼酒醉湖边',
