'簟谁分长物，酒并缺贤人',
'道士携壶酒，相迎劝瓦卮',
'今朝才酒债，明日有柴钱',
'酒可吾中孰圣贤，定开愁眼耸吟肩',
'饮湿自嫌无圣酒，摘鲜犹幸有真茶',
