'岂惟无酒酤，不复有床眠',
'雪后蒌蒿初荐酒，花前蛱蝶欲穿衣',
'岂无一杯酒，脯茹与同挥',
'君幸有美酒，何不频沾唇',
'乐兮携佳人，樽酒相追随',
'我有平生八叉手，兴来举酒尚洋洋',
'邂逅同倾九日酒，凄凉暗诵十年诗',
'酒胆一何大，和陶效坡颍',
