'酌尔一杯酒，留我壮且肥',
'薛子善饮酒，口如汲水虬',
'自忘府中官，取酒石上斟',
'试饮此亭酒，自惭缨上尘',
'二君为我重置酒，席上醉倒交相扶',
'过恶酒色间，可罪非可恶',
