'临风举酒千钟尽，步月吹笳十里声',
'为我具斗酒，宿恨犹可偿',
'它年逢九日，杯酒逐英豪',
'明朝尚肯过吾饮，有酒不尽行将酸',
'樽酒怜君偏好客，诗篇寄我谬知音',
'数举除夜酒，稍消少年豪',
'西归凉冷霜风后，浊酒清诗谁与亲',
