'何时对樽酒，重为洗埃尘',
'经秋卧病闻斤响，此日登临负酒船',
'访我不嫌泥正滑，留君深愧酒非醇',
'自言五色苦乱目，况乃旨酒长伤脾',
'清秋九日近，菊酒皆可得',
'褰帷顾我笑，疑我困宿酒',
'相逢话禅寂，落日共杯酒',
'呼儿具浊酒，酒酣起长歌',
'山深瘴重多寒势，老大须将酒自扶',
'尉佗城下两重阳，白酒黄鸡意自长',
'一枝遗我拄寻君，老酒仍烦为开瓮',
