'老人发少花头重，起舞欹斜酒力匀',
'老夫方苦贫，不办酒如渑',
'风前隔年曲，瓮里重阳酒',
'菊生墙下不知节，酒滴床头初满樽',
'家人欲酿重阳酒，香曲甘泉家自有',
'春初种菊助槃蔬，秋晚开花插酒壶',
'菊迟知岁闰，酒贵念人饥',
'谁凿西湖十里中，扁舟载酒飏轻风',
'白须照水湖光净，渌酒留人鸟哢频',
'冰酒黄封生不喜，春芽紫笋向谁求',
'脾病家人不教饮，官厨好酒亦难求',
'解衣换村酒，酒薄不须嫌',
'送酒谁知我，瓢樽昨暮干',
'心空莫著书千卷，客到长留酒半缸',
'吾道凭温酒，时情付拥炉',
