'山家十钱得升酒，劝我引觞聊沃饥',
'人生嗜好亦天然，岂顾书淫与酒癖',
'书固吾不能，酒亦久不吃',
'长沙春正妍，樽酒会嘉客',
'溪上一杯酒，送君今几时',
'酌我一樽酒，送君千里行',
'我欲劝众生，舍酒求明慧',
'如佛之所说，饮酒多过患',
'若欲常不死，彼人应舍酒',
'酒为毒中毒，地狱中地狱',
