'平生饮酒不尽味，五鼎馈肉如嚼蜡',
'昨来杜鹃劝归去，更待把酒听提壶',
'得钱百万送酒家，一笑不问今余几',
'与世浮沈惟酒可，随人忧乐以诗鸣',
'蓬窗高卧雨如绳，恰似糟床压酒声',
'酌酒时在傍，可用弭楚氛',
'王郎颇病金瓢酒，不耐寒花晚更芳',
'至今凛凛有生气，饮酒真成不愧天',
