'酒兴情亲俱不浅，贱生何取罄交欢',
'父怜母不诃，日以浊酒浇',
'苦思梦春草，醉狂眠酒家',
'青灯哦妙句，如酌春酒滑',
'未见历下人，徒倾历城酒',
'公有一杯酒，与人同醉醒',
'竹下倾春酒，愁阴为我开',
'黄花不举酒，佳句余嫪恋',
'时通问字人，得酒未曾辞',
'酒因咀嚼还知味，诗就呻吟不要工',
'琼瑶万里酒增价，桂玉一炊人少钱',
'酒肉令人肥，蒿蔓令人瘦',
