'以兹敢倾一杯酒，为太夫人千万寿',
'苦寒无处避，惟欲酒中藏',
'何当楫迎汝，秦淮绿如酒',
'何时快登临，篙师分牛酒',
'一试金仆姑，归饮软臂酒',
'万钱买酒从公醉，一钵行歌听我颠',
'江头酒贱樽屡空，南山有田岁不逢',
'沽酒鸟劝人，怀贤吾忘我',
'初尝不可口，醇酒和味宜',
'八月酾社酒，公私乐年登',
'夜语倒樽酒，参旌偃风旒',
'百年几会合，美酒不屡醺',
'愿多载酒人，喜我识字博',
'故人昔在国北门，邻舍杖藜对樽酒',
'浣花酒船散车骑，野墙无主看桃李',
'莫听游人待妍暖，十分倾酒对春寒',
'李苦少人摘，酒醇无巷深',
'万事尽还杯酒里，百年俱在大槐中',
