'病酒相如在行役，梁王谁与共清樽',
'天香国艳不着意，诗社酒徒空得名',
'万金一醉张公子，莫道街头酒价添',
'传声为向扬州问，相忆犹能把酒不',
'酒壶自是华胥国，一醉从他四大忙',
'黄花一樽酒，期与尔同斟',
'纵有黄花堪对酒，应无红袖与传杯',
'家贫无酒愿邻富，官冷有田知岁丰',
'长为扶头欠斗酒，不关禅病减腰围',
'碧酒尚堪遮眼醉，红榴不解替人愁',
