'朝欢夕宴奉歌酒，春去秋来情愈厚',
'从教弄酒春衫涴，别有风流上眼波',
'夫何稍除去，乃自得醇酒',
'得志亦遄归，我有贺酒杯',
'体畅宁须酒，神和不让春',
'便无游览分，樽酒幸相亲',
'送花盘上春情重，卖酒垆前醉魄雄',
'茆屋读书风满座，野桥寻酒月当头',
'半轩风竹一樽酒，冷笑世途争富贫',
'古书似我闲千卷，山酒从谁尽十分',
'风豪雨横伤鶑蝶，酒冷诗荒负管弦',
'已从酒盏忘千虑，羞看贪人校一毛',
'酒缾虚卧琴弦暗，眼见风光似九秋',
'酒客胸襟亦自贤，平生不断醉因缘',
'酒为忧民倾日月，诗从思退写烟霞',
'官池公载酒，痛饮消日月',
'饮酒或一醉，万物如埃尘',
'诗酒两不得，坐愧桃花林',
'是时闻尔劝沽酒，下马解带留长亭',
'谁来沽酒饮，自笑典衣难',
'纵酒偶然因客至，行歌浑不用人扶',
'不妨痛饮相牵率，待把生涯付酒杯',
