'虽有风光堪共赏，自怜诗酒属吾家',
'入城那复得逍遥，酒熟花开却见招',
'每到题诗偏得趣，自怜把酒不能歌',
'乱插乌巾酬老健，轻浮白酒惜春归',
'古人醉以酒，盖亦有所寓',
'更辱邀我临山冈，大壶载酒冽鼻香',
'我来卧松檐，斗酒客颜酡',
