'咙唿马子踏落花，落花尽头逢酒家',
'业诗何水部，耽酒阮兵曹',
'消日棋千局，忘怀酒一瓯',
'破闷无如酒，消忧莫若棋',
'欲穷人目逢山好，未老秋容到酒醇',
'主意十分浓似酒，客心一缕急于滩',
