'笑我徜徉吴楚间，经卷酒卮随所遇',
'或时得名酒，亭午犹中圣',
'岂无一樽酒，谁与通殷勤',
'春深𫛸鴂催诗句，夜静蟾蜍入酒舟',
'顾我行为大梁役，一卮薄酒话愁肠',
'太平谁谓全无象，寓在群仙把酒时',
