'月动融尊酒，花催郑驿宾',
'七年三过白苹洲，长与诸豪载酒游',
'张公吃酒李公醉，自古人言信有之',
'百壶天酒凝甘露，二雅宸章掩大风',
'芳樽长有酒，嘉树自成蹊',
