'雨过云收山泼黛，管弦歌动酒家楼',
'花月病怀看酒谱，云萝幽信着茶经',
'不饮知酒趣，聊复酌公浆',
'光翠相动摇，照我尊酒绿',
'无酒或过雄，有酒谁馈伋',
'不如置之酌美酒，同郡诸公皆旧游',
'相看乏酒饮，愁剧似渊明',
'载酒从今相煖热，著书应不号穷愁',
