'樽前有酒同偓佺，明朝且笑云山巅',
'岂无尊中酒，非君谁与倾',
'岂无樽中酒，对之空叹嗟',
'风回惊怨落红飞，把酒临溪倚花树',
'载酒展席俯长流，一饭未尝留俗客',
