'越客登临兴何有，愁不能言病妨酒',
'过门把酒豁清襟，行将归隠南山阴',
'每寻不浅胡床兴，更有歌人行酒筹',
'虽夸酒无算，饱德何由丰',
'独挹一樽酒，悲歌送徂春',
'樽酒少迟留，禅林见凉月',
'山川气候美，诗酒风神王',
'夙昔一樽酒，相从清泗滨',
'坐上一樽酒，江南千里春',
'惜无一樽酒，幸与之子同',
'当年孟张辈，载酒来行乐',
'酒酣望三山，宛在青天外',
'何人具供帐，樽酒展殷勤',
'载酒定何时，新黄糁庭菊',
'酒阑应有待，梦破即无缘',
'故园桃李在，樽酒愿相亲',
'黄华一樽酒，何处望吾乡',
'朝风占酒旆，夜爨乞渔灯',
'离忧不可解，罢酒独登临',
'老圃念人留𥩟久，挽衣沽酒愿相过',
