'定无佳客清樽酒，赖有古人黄卷书',
'一樽通济桥边酒，两夜临濉驿外钟',
'可须樽酒平生约，长望西州泪满巾',
'六朝陈迹何须问，一曲沧浪酒十分',
'风雨扁舟幸少留，为君持酒话徐州',
'昔年九日登临处，把酒梁王旧吹台',
'浊酒纵贤谁与醉，青山有价不容赊',
