'樽酒津亭别，还城何所投',
'东轩美风月，诗酒伴欢呼',
'霜空出华月，樽酒聊相对',
'不见会之久，每思诗酒豪',
'前春应上冢，能访酒家无',
'别酒厌厌一据鞍，远林微迳雪迷漫',
'白衣送酒无消息，赖有西邻张长公',
'几对春风把酒杯，小舟临发更徘徊',
'浮生欲寄酒杯间，马上谁容一日闲',
'楼外浮云何可攀，聊持樽酒共销闲',
