'老去才先尽，春来酒屡空',
'人生亦何须，有酒与桐君',
'声中得句已忘言，断酒持斋却自然',
'惟酒可为娱，顾我非其流',
'生前一樽酒，拨弃独何易',
'坐想明年吴与越，行酒赋诗听击钵',
'已须甘酒力，不用占时名',
'独无樽酒为君寿，正使秋花未肯黄',
'佳辰难得客更难，我穷无酒为君欢',
