'荣枯何足计，有酒还自倾',
'时时载酒往，江上亦忘回',
'为州第饮酒，况此年岁好',
'安得如江酒，洗我尘垢情',
'耆酒不疵吝，身如秋叶轻',
'红妆拥坐花照酒，青萍拔鞘堂生风',
'阴山射虎边风急，嘈杂琵琶酒阑泣',
'未劳负米迂山川，姑弟酒中从圣贤',
'漫浪饮处空有迹，无酒可沃胸崔嵬',
'平生豪气对樽酒，山鸡见镜犹能舞',
'东风浩浩吹榆柳，相劝西城古原酒',
