'绿鬓哦诗欲成雪，朱颜得酒尚能春',
'酒怜旁舍熟，赋喜故人能',
'北省主人夸酒好，南风稚子喜帆开',
'久乾文举尊中酒，虚负渊明头上巾',
'相逢樽酒未辞深，握手盱眙十载心',
'广文不去惭官长，系马堂阶要酒钱',
'载酒五湖狂到死，只今天地不能藏',
