'兴来出饮酒，兴罢归杜门',
'期归酌烧酒，及此未炎燠',
'悠然有佳兴，美酒时一倾',
'荒狂有何乐，徒以酒自名',
'狂言无为发，浊酒醉自劝',
'油然有好怀，日暮归饮酒',
'我初谪官时，帝问司酒神',
