'久知无朋酒，出没均酩酊',
'如何二毛初，蒿里浇絮酒',
'吴天千古月，空照酒家垆',
'亦欲相追老湖海，稽山肯放酒船回',
'漉酒空峨五柳巾，一觞相属念情亲',
