'我观他日诗，说酒特未已',
'独此止酒诗，字字如信史',
'阮籍刘伯伦，嗜酒不知止',
'无心穷酒圣，有意造诗史',
'凭君为唤诗肠温，他日有酒不足论',
'伊昔苕水滨，诗酒相逆送',
'况有载酒人，半道同栗里',
'未妨浊酒陪心赏，更借清诗作眼明',
