'天上频移玳瑁筵，琼浆赐酒如流泉',
'酒会驱愁常恐薄，诗能穷我不须工',
'携酒却来湖上寺，不堪重对小孱颜',
'满倾吴地千钟酒，细说长安六度春',
'相逢又残岁，话酒几青春',
