'秫堪醸酒醉不醒，饭可充饥饱摩肚',
'旧来持酒听歌处，乞与东风燕子飞',
'多酿醉乡千日酒，岂知浮世十朱轮',
'无诗可说难言态，有酒应须着意携',
'斗酒只鸡吾欲哭，不知谁为作侯芭',
'斗酒淋漓浇宿草，西风老泪不胜多',
'醉到湖边谁共酒，别来江上苦无书',
'日暖鱼增价，风和酒易沽',
'列坐流觞能几日，知谁对酒爱新鹅',
'仍携缥缈人，有酒可酙酌',
'茶称瑞草世所珍，酒为美禄天之有',
'何时却得同樽酒，弟劝兄酬笑语喧',
'酒后笑谈无畔岸，更将妙道问鸿蒙',
'闲如白傅不饮酒，穷似虞卿懒著书',
