'开怀酒一壶，寓意棋一局',
'酌此一壶酒，宠辱那复惊',
'举世人事伪，惟酒存天真',
'照眼一编书，开怀一壶酒',
'酌酒自起舞，与之相献酬',
'有酒且觞客，无弦何用琴',
'无心问渔父，浊酒慰平生',
