'我爱昭州酒，千家不禁烧',
'栽近木兰殊有意，留连文酒系春风',
'酒户棋兵孰与侪，月宵曾遇六天街',
'架上书千卷，花前酒一尊',
'有酒聊自把，无萱良鲜欢',
'安得盈觞酒，时复中圣贤',
'雪情欺酒薄，月思拂琴寒',
'渠渠持美酒，计日望归轩',
