'未辞酒炙为公费，政恐亲知见面稀',
'长愧邻翁酒，囊空尚可賖',
'殷勤一杯酒，目送西归鸿',
'畏病还疏酒，逃寒懒见人',
'借问典衣充戏责，何如沽酒唤吾曹',
'白酒红灯称意春，知公未免踏黄尘',
'床头有酒须君醉，又废蒲团一夜禅',
'何处青帘足沽酒，粥香饧白是今年',
'停车问缩酒，不讣牛马风',
'沈郎爱客如爱酒，章子问诗如问禅',
'忆昔泊船鹅翎口，把酒遥为故人寿',
'中郎卧病过春晚，昔则酒狂今诗瘦',
'尊酒相逢十载前，绿发红颜俱少年',
