'青帘白酒斜阳外，不与行人满眼酤',
'薄酒残灯欲别情，暗萤依草不能明',
'酒忆侯公圣，月如京兆眉',
'病去只留花作伴，客来常欠酒应门',
'客子三杯玉泉酒，主人一曲浪淘沙',
'一杯冻酒君莫辞，预借炎天洗烦热',
'酒薄如官冷，年丰荷主恩',
'旦日过城南，把酒公一醉',
'唤客不须嫌酒恶，隔墙时喜送橙香',
