'便期载酒约来冬，似要恶诗相抵触',
'对酒我不饮，把盏君当歌',
'酒炙虽勤主人费，且幸吾党频相过',
'端如贮美酒，妙处当自斟',
'得君双榼酒，起我终日病',
'爱客能忘酒，长贫不废诗',
'药囊往往充诗藁，米劵时时当酒钱',
'长贫不贳酒，虽健懒登楼',
'主人不厌客，敢辞酒杯深',
'酒壶茶具偏宜坐，细草残花别是春',
'从来不饮酒，万事付茗碗',
'会约君家好兄弟，他年尊酒便相从',
'犹记往来寒食下，客房无酒卧空瓶',
'初无一尊酒，慰君别后思',
'只应此去添憔悴，又欠先生酒一尊',
'君为千里行，我有一尊酒',
'我来拜遗像，肴蔬荐芳酒',
'早来取酒瓶已空，对盏不复能从容',
'岁时社酒会，扶醉有年高',
'茅酒沽来常满斗，白鱼买得不论钱',
