'且喜春盘兼守岁，莫嗟腊酒易经年',
'诗穷莫写愁如海，酒薄难将梦到家',
'祝君樽酒醉罗裳，此夜应须石作肠',
'门前亦有酒，官禁不可酤',
'行人不忍别，遇酒辄醉倒',
'已是春如酒，那堪尔似绵',
'我有一樽酒，为君消百忧',
'傲兀不能寝，取酒聊相酬',
'归怀止惋结，赖此杯酒寛',
