'酒轻离思重，目短大江流',
'秋高霜露寒，酒热鲈鱼美',
'短吟五七字，薄酒三四酌',
'格瘦诗难写，香寒酒易空',
'野径菊仍好，村垆酒亦嘉',
'白石青霞为岁计，佳殽旨酒出仙壶',
