'苜蓿重沽酒，芝麻旋点茶',
'想斟新社酒，多读盛唐诗',
'对琴思古意，酾酒惜韶光',
'鸿门罢樽酒，舞剑事还差',
'欲酒对黄华，乌纱奚足爱',
'有酒斟酌之，欢然成喧哗',
