'欲携斗酒，怕上高楼',
'翠缕香凝，玉膏酒滟',
'深院笙歌，劝饮金钟酒',
'尊酒团栾，莫惜通宵醉',
'药市家家帘幕，酒楼处处丝簧',
'又烧灯市井，卖酒楼台',
'载酒郊坰修禊事，雅称兰舟同泛',
'倦游处，减羁愁，犹未消磨是酒',
'秀色通帘，生香聚酒，修景常留池沼',
'温泉浴罢，酣酒才苏，洗妆犹湿',
'频唤酒，渔屋岸西头',
'燕帘莺户，云窗雾阁，酒醒啼鸦',
'麾去茶经，袭藏酒颂',
