'门外残红春已去，镇无聊、𣨼酒厌厌病',
'帘外残红春已透，镇无聊、𣨼酒厌厌病',
'谁信而今，怕愁憎酒，对着花枝，自疏歌笑',
'沈湘人去已远，劝君休对酒，感时怀古',
'且斗尊前酒美，莫问楼头佳丽，往事有无中',
'记竹里题诗，花边载酒，魂断江干春暮',
'座上骑鲸仙友，笑我胸中磊磈，取酒为浇愁',
'道酒能消遣，酒因病减，歌能消遣，歌为愁浓',
'随分绿酒黄花，联镳飞盖，总龙山豪客',
'望一簇画楼，记沽酒处，几多鸣橹，争趁潮归',
