'宁可且将朱唇饮酒，谁能遂你黑齿常之',
'春酒香熟鲈鱼美，谁同醉，缆却扁舟篷底睡',
'独头大蒜乌梅肉，速将酒煮便能痊，谨记此良言',
'酒场是太后教令，问你还有耳孔也无',
'公归肯访老翁否，酤酒满眼未必然，青刍白饭聊随缘',
'老夫不愿万户侯，但愿与君酒船万斛同拍浮',
'唐林晁错莫逢它，高阳酒徒咀尔不摇牙',
'酌君以乌程若下之酒，赠君以鲁山于𫇭之声',
'酒以惜在原兄弟之别，歌以见爱民父母之情',
'击鼓其镗山之下兮，桂酒椒浆饯神去兮',
'洛阳城中亦有园与宅，常同欧阳翰林携酒游',
'空令便桥乞盟未央酒，盛事拂膺正观时',
'祝子来过勿踌躇，堆床败简翻蠹鱼，共倒浊酒羹瓠壶',
'酒它酒，总弗右，陂草草深别宇宙，野香薰蒸喷饙馏',
'饮君以蜀州竹叶之酒，食君以郦县菊花之英',
'蟠桃入口那能甘比蜜，湛溪不抵酒滴真珠槽',
'刘郎气豪酒豪诗更豪，乃肯折节作赋遗恨无纤毫',
'诗雄赋老不入世俗眼，仰空大叫索酒歌离骚',
'以蜜为酒，昉于东坡，托诗以传，百世不磨',
'君看行乐且随分，不用美酒丽女骄目前',
'邀翁问所得，共入酒家保，买以十万青铜钱',
'酒酣忽转商声急，龙君悲咤波臣泣，锦瑟无端弦五十',
'只可茅柴火酒醉几觞，村田乐诗吟数首',
'田公姥，侬肴芬芬兮侬酒湑湑，官税既输兮公役不烦',
'红炉锦帐羔酒斟，岂识盘车图中意愁绝',
'文人才士过从每樽酒，樵夫牧子亦许荆同班',
'四时更变化，宋玉胡为愁，直须痛饮千斛酒',
'幕中宾从才且良，酒酣落笔摛文章，珠联璧叠争炜煌',
'神郁葱佳气晓笼天，北斗倾霞入酒舡',
'窈窕芙蓉新出水，嘈嘈弦管鸾凤鸣，玉卮献酒公解酲',
'犹将公田二顷五十亩，种秫作酒不种秔',
'薄薄酒，胜茶汤，粗粗布，胜无裳，丑妻恶妾胜空房',
'蠢蠢万类随江河，肯同儿女战蜗角，酒酣雨泪挥滂沱',
'弭余楫兮饮君酒，君既不顾兮驾龙以出游',
'行者怀兮别者思，酌君酒兮寿君以不衰',
'逐客衣冠尚褴缕，故欲下非坚敌，试举酒兵令',
'投我以建溪北焙之新茶，报君以乌程若下之醇酒',
'酒酣拔剑起为寿，剑光棱棱入牛斗，不放浮云变苍狗',
'秀脸拂新红，酒入娇眉眼，薄衣减春寒',
'宝津南殿，宴坐近天颜，金杯酒，君王劝',
'好惜取、韶华醉连宵，更莫待、收灯酒阑人去',
'好是斜月黄昏，瑶阶钿砌，百媚初含酒',
'断肠一曲金衣，两行玉箸，酒阑后、欲行难去',
'我已从头识破，赢得当歌临酒，欢笑且随宜',
'行时载酒寻芳，湖湾堤曲，放浪红尘脚',
'百岁光阴难挽，一笑欢娱易失，莫惜酒盈卮',
'遇酒开颜，逢欢乐意，有似木人骑土牛',
'独把瓦盆盛酒，自与渔樵分席，说伊政声佳',
'手栽一色红梅，香笼十亩，忍轻负、酒肠诗兴',
'翠袖传觞，金貂换酒，痛饮何妨三百杯',
'涧边野鹤，岩上忽孤云，倾浊酒，对黄花，又似东篱子',
'开遍门前丹蕊，渐西风入东篱，酿成仙酒',
'看画城簇簇，酒肆歌楼，奈没个巧处，安排着我',
'尊酒唤回和气在，看从来、兄弟依然好',
'秦楼屡约芳春，记扇背题诗，帕罗沾酒',
'我被五斗红陈，三升官酒，驱到郪城北',
'贵介时豪，搢绅处士，未解先生酒适情',
'唤起东风，吹醒宿酒，把甲子从头重数将',
'待持酒高堂、劝东皇，且爱惜芳菲，留春借暖',
'况值清和时候，正青梅未熟，煮酒新开',
'看鱼肥蟹健，妻孥共乐，酒�璧臼欤�翁媪相将',
'玉漏声沈，银潢影泻，𣨼酒犹烧心字香',
'且约携酒高歌，与鸥相好，分坐渔矶石',
'宿酒难醒，多情易老，争奈传杯不放杯',
'笑指白云归去好，对夕阳、泻酒凭谁荐',
'袖里宝剑生寒，中宵起舞，引酒清歌发',
'天下英雄，使君与操，余子谁堪共酒杯',
'叹名姬骏马，都成昨梦，只鸡斗酒，谁吊新丘',
'忙脱征衫，快呼斗酒，细为家人说建溪',
'老去胸中，有些磊块，歌罢犹须著酒浇',
'青杏园林，朱樱酪酒，争似和羹雪后梅',
'叹酒泉郡远，醉乡路绝，今何处、堪开国',
'已被色香撩病思，尽鹅儿、酒美无多酌',
'我有丰淮千斗酒，把新愁、旧恨都倾倒',
'记湘滨露冷，酥容倍洁，华清水滑，酒晕全消',
'试向商乐亭前，冷风台上，把酒招黄鹄',
'纵葵榴花闹，菖蒲酒美，都成客里，争似家边',
'堪羡麦熟蚕成，酒香鸡嫩，风味农家别',
'掩窗绡，待得香融酒醒，尽消受、这春思',
'箫鼓晴雷殷殷，笑歌香雾霏霏，闲情不受酒禁持',
'东园曾趁花前约，记按筝筹酒，戏挽飞琼',
'遇笔题诗，逢人饮酒，世间万事，看尽多多少少',
'闻道凝碧池边，宫槐叶落，舞马衔杯酒',
'乱莺声残酒醒，正是关情，山枕上、吟就回纹锦句',
'向琐窗看镜，鬓无霜白，玉舠挥酒，脸有潮红',
'一笑蔷薇孤旧约，载酒寻欢，因甚懒支持',
'对一尊、别酒初斟，征衫上、点滴香泪盈',
'想荒坟酹酒，过车回首，香魂携手抱相泣',
'骰选功名，酒中富贵，管取当筵满劝旬',
'闻道酿桃堪为酒，待酿桃、千石成千醉',
'忍记倚桂分题，簪花筹酒，处处成陈迹',
'次第重阳近也，看黄花绿酒，也合迟留',
'掩面鸣筝，倚垆呼酒，东风重记旧眉妩',
'杯酒凤凰台上，对石城流水，钟阜诸峰',
'经行几度怨别，酒痕消未尽，空被花恼',
'合捧金荷称鹤算，想华堂、剩醉眉春酒',
'玉燕当年储瑞气，记垂弧、共醉蓬莱酒',
'拟办羔儿香瓮酒，唤刘叉、来醉尊前约',
'烟惹宫城深树，日照酒楼帘幕，物象眼前排',
'问旅情如许，怎生排遣，应费酒尊诗轴',
'且把梅花酌酒，行即桂枝入手，桑荫未移阴',
