'看门贴绘鸡，历颁金凤，酒浮柏叶，人颂椒盘',
'向此际、色映堂阴，香传梅影，寒力更欺尊酒',
'阆苑凝夕，瑶窗淡月，百琲寻芳，醉玉谈群，千钟酹酒',
'行行游赏，邂逅得诗人，呼斗酒，发清吟，豪气凌霄汉',
'衰颜易改，不用看传神，欢意浅，酒肠悭，孤负深深劝',
'杜荀鹤尝吟一联诗云：旧衣灰絮絮，新酒竹𥬠𥬠',
'宁可且将朱唇饮酒，谁能逐你黑齿常之',
'翠蛾争劝临邛酒，纤纤手，拂面垂丝柳',
