'曾是瑶妃清瘦，帝与金丹换骨，酒韵上韶颜',
'几回唤酒寻诗，诗成小醉，絮帽浑敧侧',
'且看戏彩堂前，酒须双献，饮侍严君侧',
'客笑欣然重酌酒，忽盘肴既尽杯狼籍',
'阳关须是醉酒，柳条休要折，争似攀桂',
'绕郡城、千顷烟波绿，正鱼肥酒美，名冠东州',
'灵龟荐祉，紫鸾称寿，千钟泛酒，百和焚香',
'好在南邻，诗盟酒社，刻烛争成，引觞愁缓',
'却欲便买茅庐，短篷轻楫，尊酒犹能办',
'新醅旋压鹅黄，拼清愁在眼，酒病萦骨',
'横钗整鬓，倚醉唱清词，房户静，酒杯深',
'待酒醒枕臂，同歌新唱，怕晓愁闻画角',
'禁篽升平，慈闱燕适，袆衣共上玉觞酒',
'揽幽芳、泛酒面香凝，携手与、仙姿共游嬉',
'朱唇晕酒，脸红微透，翠纱轻卷，红映丰肌',
'乍过了挑青，名园深院，把酒偏宜细步',
'斜入酒楼歌处，微褪茅檐烟际，窗户漾光寒',
'与客同，清欢扣舷歌咏，开怀饮酒情酣畅',
'一杯薄酒何足御此大愤怨，不如愚无知者酣卧鼻息长如雷',
'行路难，劝君酒，莫辞烦，美酒千钟犹可尽，心中片愧何可论',
'君不见屯军十万如貔貅，椎牛酾酒不得饱，飞刍挽粟无时休',
'君不记南方无此物，五更酒渴唤水时，思此千里莫致之',
'此时此意，危魂黯黯，渭城客舍青青树，问何人、把酒来看别',
'休烦恼，劝君更尽一杯酒，只恐怕、西出阳关，旧游如梦，眼前无故人',
'微风帘幕清明近，花落春残，尊酒留欢，添尽罗衣怯夜寒',
'作笺天公拜稽首，乞我此老生时一双手，为君痛饮百斛酒',
'君不见柴桑于酒特寓意，相逢不择贱与贵，要是醇醨均一致',
'唤小艇、渔翁鹤发，凛冽寒风吹酒面，与何人、共泛山阴月',
'到家但见妻与子，赖得饮君春酒数十杯，不然令我愁欲死',
'马嘶人语春风岸，芳草绵绵，杨柳桥边，落日高楼酒斾悬',
'昨因黑月二十五，初夜饮酒醉，两人相浑杂，种种调言气',
'不如且饮酒，耳热徒歌讴，可以销遣绵绵不断万古之悲愁',
'诗题：饮酒四首首句：我观人间世左手持蟹螯有客远方来雷觞淡于水',
'又不见大舅小舅兄弟专晋亦何有，兄招千里兵，弟殒一杯酒',
'记当年，赋得一丘一壑，天鸢阔，渊鱼静，莫击磬，但酌酒，尽从容',
'忆几度、微吟马上，长啸舟中，惯踏新丰巷陌，旧酒犹香，憔悴东风自岁华',
'谩淡却蛾眉，晨妆慵扫，宝钗虫散，绣屏鸾破，当时暗水和云泛酒，空山留月听琴',
'”时杨妃侍，上曰：“妆台前宜饮以一紫金盏酒，则正封之诗见矣',
'时人见其纵逸，姿貌非常，每饮酒食鲊，疑为陶之夫妇焉',
'却思公之文字世莫双，举酒一使长咽慢肌高揭鼓笛腔，万古有作心胸降',
'广陵老人争持壶酒，朝言送少年使君，暮言迎少年太守',
'与夫皮为冠兮叶为酒，皆自荆阳之贡东南之美兮，冒霜停雪拂景云而萦惠风',
'朱方豪士森戈矛，青云蹭蹬犹督邮，不如黄鸡白酒相与醉即休',
'登山宴水，横江酹酒，倾将慷慨酬形势，付兴亡、一笑翻歌舞',
'聿修伺述酒翁将竭，叩门求饮，未通大道，已见罍耻，濡笔书壁曰〖诗略〗',
'彼作福之臣兮烹煎牛羊罗列酒浆，我方折其匕箸兮覆杯而不尝',
'帘上涌金楼，酒滟酥融，金缕试春曲，最好半残𫛛鹊，登临快心目',
'酒阑睡觉天香煖，绣户慵开，香印成灰，独背寒屏理旧眉',
'宋齐丘送于郊次，酒行语熟，使者启令曰：须啖二物，各取南北所尚，复以二物，仍互用南北俚语',
'酌瑶尊之芳酒兮招赤松而友彭祖，既锡我以难老兮黜嗜欲而袭灵虚',
'谁更与、苔根洗石，菊井招魂，漫省连车载酒，立马临花，犹认荐红傍路枝',
'列笾豆为左右兮苹藻牲牢而洁肥，酌玉醴以为酒兮错琼瑶而为粢',
